import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../../context/LanguageContext';
import { Card, CardContent } from '../../ui/card';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '../../ui/tabs';
import { Button } from '../../ui/button';
import { BarChart, LineChart, PieChart } from '../widgets/Charts';
import StatsOverview from '../widgets/StatsOverview';
import OffersCarousel from '../widgets/OffersCarousel';
import TransactionManager from '../widgets/TransactionManager';
import { supabase } from '../../../lib/supabaseClient';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

// Placeholders for base64 logos
export const COMPANY_LOGO_BASE64 = 'data:image/png;base64,'; // TODO: Replace with your base64 logo
export const COAT_OF_ARMS_BASE64 = 'data:image/png;base64,'; // TODO: Replace with your base64 coat of arms

export default function BusinessHubPanel() {
  const { t } = useLanguage();
  const [tab, setTab] = useState('overview');

  // Supabase data states
  const [sales, setSales] = useState<any[]>([]);
  const [rentals, setRentals] = useState<any[]>([]);
  const [inventory, setInventory] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    setLoading(true);
    Promise.all([
      supabase.from('sales').select('*').order('created_at', { ascending: false }),
      supabase.from('rentals').select('*').order('created_at', { ascending: false }),
      supabase.from('cars').select('*').order('created_at', { ascending: false })
    ]).then(([salesRes, rentalsRes, carsRes]) => {
      if (salesRes.error || rentalsRes.error || carsRes.error) {
        setError(salesRes.error?.message || rentalsRes.error?.message || carsRes.error?.message || 'Error fetching data.');
      } else {
        setSales(salesRes.data || []);
        setRentals(rentalsRes.data || []);
        setInventory(carsRes.data || []);
      }
      setLoading(false);
    });
  }, []);

  const tabList = [
    { key: 'overview', label: t('Overview') || 'Overview' },
    { key: 'sales', label: t('Sales') || 'Sales' },
    { key: 'rentals', label: t('Rentals') || 'Rentals' },
    { key: 'inventory', label: t('Inventory') || 'Inventory' },
  ];

  // Helper: format currency
  const formatCurrency = (amount: number, currency: string = 'KES') =>
    new Intl.NumberFormat('en-KE', { style: 'currency', currency }).format(amount);

  // PDF export helpers
  const exportPDF = (rows: any[], filename: string, title: string) => {
    if (!rows.length) return;
    const doc = new jsPDF();
    if (COMPANY_LOGO_BASE64) doc.addImage(COMPANY_LOGO_BASE64, 'PNG', 10, 10, 30, 30);
    if (COAT_OF_ARMS_BASE64) doc.addImage(COAT_OF_ARMS_BASE64, 'PNG', 170, 10, 30, 30);
    doc.setFontSize(18);
    doc.text(title, 105, 50, { align: 'center' });
    doc.setFontSize(12);
    doc.text('Justice Ultimate Automobiles', 105, 60, { align: 'center' });
    doc.text('Date: ' + new Date().toLocaleDateString(), 105, 68, { align: 'center' });
    (doc as any).autoTable({
      startY: 80,
      head: [[...Object.keys(rows[0])]],
      body: rows.map((r: any) => Object.values(r)),
      theme: 'grid',
      headStyles: { fillColor: [34, 197, 94] },
    });
    doc.setFontSize(10);
    doc.text('Digital Signature:', 10, doc.internal.pageSize.getHeight() - 30);
    doc.line(45, doc.internal.pageSize.getHeight() - 32, 120, doc.internal.pageSize.getHeight() - 32);
    doc.save(filename);
  };

  return (
    <Card className="w-full max-w-6xl mx-auto bg-gradient-to-br from-green-50 to-green-100 dark:from-green-950 dark:to-green-900 shadow-2xl border-0">
      <CardContent className="p-8 space-y-8">
        <h1 className="text-4xl font-extrabold text-green-900 dark:text-green-200 tracking-tight mb-2 font-serif">{t('Business Hub') || 'Business Hub'}</h1>
        <p className="text-lg text-green-700 dark:text-green-300 mb-6 font-medium">{t('businessHubDesc') || 'Centralized control for sales, rentals, inventory, and real-time business insights.'}</p>
        {loading ? (
          <div className="text-center text-green-700 dark:text-green-200 text-lg font-semibold py-12">{t('Loading data...') || 'Loading data...'}</div>
        ) : error ? (
          <div className="text-center text-red-600 dark:text-red-400 text-lg font-semibold py-12">{error}</div>
        ) : (
        <Tabs>
          <TabsList>
            {tabList.map(tabItem => (
              <TabsTrigger
                key={tabItem.key}
                label={tabItem.label}
                selected={tab === tabItem.key}
                onClick={() => setTab(tabItem.key)}
              />
            ))}
          </TabsList>

          {tab === 'overview' && (
            <TabsContent>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div>
                  <StatsOverview />
                  <OffersCarousel />
                </div>
                <div className="bg-white dark:bg-green-950 rounded-xl shadow-lg p-6 flex flex-col gap-6">
                  <h2 className="text-2xl font-bold text-green-900 dark:text-green-100 mb-4 font-serif">{t('Business Analytics') || 'Business Analytics'}</h2>
                  <div className="mb-4">
                    <span className="text-lg font-semibold text-green-800 dark:text-green-200 mr-4">{t('Total Sales') || 'Total Sales'}:</span>
                    <span className="text-2xl font-bold text-green-900 dark:text-green-100">{formatCurrency(sales.reduce((sum, s) => sum + (s.amount || 0), 0))}</span>
                  </div>
                  <div className="mb-4">
                    <span className="text-lg font-semibold text-green-800 dark:text-green-200 mr-4">{t('Total Rentals') || 'Total Rentals'}:</span>
                    <span className="text-2xl font-bold text-green-900 dark:text-green-100">{formatCurrency(rentals.reduce((sum, r) => sum + (r.amount || 0), 0))}</span>
                  </div>
                  <div className="mb-4">
                    <span className="text-lg font-semibold text-green-800 dark:text-green-200 mr-4">{t('Total Inventory') || 'Total Inventory'}:</span>
                    <span className="text-2xl font-bold text-green-900 dark:text-green-100">{inventory.length}</span>
                  </div>
                  <BarChart title={t('Sales by Month') || 'Sales by Month'} />
                  <h3 className="text-lg font-semibold text-green-800 dark:text-green-200 mb-2">{t('Revenue Breakdown') || 'Revenue Breakdown'}</h3>
                  <PieChart />
                  <TransactionManager />
                </div>
              </div>
            </TabsContent>
          )}

          {tab === 'sales' && (
            <TabsContent>
              <div className="space-y-6">
                <h2 className="text-3xl font-bold text-green-900 dark:text-green-100 font-serif mb-2">{t('Sales') || 'Sales'}</h2>
                <p className="text-green-700 dark:text-green-300 mb-4 font-medium">{t('salesDesc') || 'Track, analyze, and manage all vehicle sales with real-time insights.'}</p>
                <LineChart title={t('Sales Trends') || 'Sales Trends'} />
                <div className="overflow-x-auto rounded-xl shadow border border-green-200 dark:border-green-800">
                  <table className="min-w-full text-sm">
                    <thead className="bg-green-100 dark:bg-green-900">
                      <tr>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Date</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Customer</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Car</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Amount</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sales.map((sale, idx) => (
                        <tr key={sale.id || idx} className="border-b border-green-100 dark:border-green-800">
                          <td className="p-3 font-mono text-green-800 dark:text-green-100">{sale.date || sale.created_at?.slice(0, 10) || '-'}</td>
                          <td className="p-3">{sale.customer_name || '-'}</td>
                          <td className="p-3">{sale.car_name || sale.car_id || '-'}</td>
                          <td className="p-3 font-semibold">{formatCurrency(sale.amount || 0)}</td>
                          <td className="p-3">
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${sale.status === 'Completed' ? 'bg-green-200 text-green-900' : 'bg-yellow-100 text-yellow-800'}`}>{sale.status || 'Pending'}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex justify-end mt-4">
                  <Button variant="primary" className="text-base font-semibold px-6 py-2 rounded shadow" onClick={() => exportPDF(sales, 'sales_report.pdf', 'Sales Report')}>{t('Export Sales Data') || 'Export Sales Data'}</Button>
                </div>
              </div>
            </TabsContent>
          )}

          {tab === 'rentals' && (
            <TabsContent>
              <div className="space-y-6">
                <h2 className="text-3xl font-bold text-green-900 dark:text-green-100 font-serif mb-2">{t('Rentals') || 'Rentals'}</h2>
                <p className="text-green-700 dark:text-green-300 mb-4 font-medium">{t('rentalsDesc') || 'Monitor rental activity, revenue, and fleet utilization.'}</p>
                <BarChart title={t('Rental Performance') || 'Rental Performance'} />
                <div className="overflow-x-auto rounded-xl shadow border border-green-200 dark:border-green-800">
                  <table className="min-w-full text-sm">
                    <thead className="bg-green-100 dark:bg-green-900">
                      <tr>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Date</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Customer</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Car</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Amount</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {rentals.map((rental, idx) => (
                        <tr key={rental.id || idx} className="border-b border-green-100 dark:border-green-800">
                          <td className="p-3 font-mono text-green-800 dark:text-green-100">{rental.date || rental.created_at?.slice(0, 10) || '-'}</td>
                          <td className="p-3">{rental.customer_name || '-'}</td>
                          <td className="p-3">{rental.car_name || rental.car_id || '-'}</td>
                          <td className="p-3 font-semibold">{formatCurrency(rental.amount || 0)}</td>
                          <td className="p-3">
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${rental.status === 'Completed' ? 'bg-green-200 text-green-900' : 'bg-yellow-100 text-yellow-800'}`}>{rental.status || 'Pending'}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex justify-end mt-4">
                  <Button variant="primary" className="text-base font-semibold px-6 py-2 rounded shadow" onClick={() => exportPDF(rentals, 'rentals_report.pdf', 'Rentals Report')}>{t('Export Rentals Data') || 'Export Rentals Data'}</Button>
                </div>
              </div>
            </TabsContent>
          )}

          {tab === 'inventory' && (
            <TabsContent>
              <div className="space-y-6">
                <h2 className="text-3xl font-bold text-green-900 dark:text-green-100 font-serif mb-2">{t('Inventory') || 'Inventory'}</h2>
                <p className="text-green-700 dark:text-green-300 mb-4 font-medium">{t('inventoryDesc') || 'Manage stock, availability, and vehicle status in real time.'}</p>
                <h3 className="text-lg font-semibold text-green-800 dark:text-green-200 mb-2">{t('Inventory Breakdown') || 'Inventory Breakdown'}</h3>
                <PieChart />
                <div className="overflow-x-auto rounded-xl shadow border border-green-200 dark:border-green-800">
                  <table className="min-w-full text-sm">
                    <thead className="bg-green-100 dark:bg-green-900">
                      <tr>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Car</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Brand</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Year</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Price</th>
                        <th className="p-3 text-left font-bold text-green-900 dark:text-green-200">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {inventory.map((car, idx) => (
                        <tr key={car.id || idx} className="border-b border-green-100 dark:border-green-800">
                          <td className="p-3 font-semibold">{car.name || '-'}</td>
                          <td className="p-3">{car.brand || '-'}</td>
                          <td className="p-3">{car.year || '-'}</td>
                          <td className="p-3 font-semibold">{formatCurrency(car.price || 0, car.currency || 'KES')}</td>
                          <td className="p-3">
                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${car.availability === 'Available' ? 'bg-green-200 text-green-900' : 'bg-yellow-100 text-yellow-800'}`}>{car.availability || 'Unavailable'}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex justify-end mt-4">
                  <Button variant="primary" className="text-base font-semibold px-6 py-2 rounded shadow" onClick={() => exportPDF(inventory, 'inventory_report.pdf', 'Inventory Report')}>{t('Export Inventory Data') || 'Export Inventory Data'}</Button>
                </div>
              </div>
            </TabsContent>
          )}
        </Tabs>
        )}
      </CardContent>
    </Card>
  );
} 